void run_production_observer_challenges(MemoryFixture &memory) {
    using namespace switch_validation::watch;
    Table observer;
    auto *write_table = observer.bind(memory.read_table->data());
    if (!write_table) throw std::bad_alloc();
    // The guard outlives jit: cleanup clears fixture pointers on every exit.
    struct Detach {
        MemoryFixture &memory;
        ~Detach() { memory.observer = nullptr; memory.active_jit = nullptr; }
    } detach{memory};
    memory.observer = &observer;
    auto config = config_for(memory, TableMode::FirstWrite, true);
    config.write_page_table = reinterpret_cast<PageTable *>(write_table);
    Dynarmic::A32::Jit jit(config);
    memory.reset_bytes();
    run_challenges(observer, memory.read_table->data(), memory.backing(0), memory.backing(1),
        kDataBase, kAliasBase,
        [&](uint32_t address, uint64_t value, size_t size) {
            memory.reset_events();
            memory.prepare(jit, size == 8 ? memory.store64 : memory.store32, address);
            jit.Regs()[1] = static_cast<uint32_t>(value);
            jit.Regs()[2] = static_cast<uint32_t>(value);
            jit.Regs()[3] = static_cast<uint32_t>(value >> 32);
            jit.Run();
            return memory.clean_stop() && memory.invalid_writes == 0;
        },
        [](const char *name, bool pass, const char *detail) {
            switch_validation::record("observer_challenge", name, pass ? "pass" : "fail", detail);
        });
    switch_validation::record("observer_challenge", "scratch_guard_pages",
        memory.guards_intact() ? "pass" : "fail", "isolated bytes only; game memory never mutated");
}

